<x-capstone::card x-show="showSchedule"><div class="px-6"><h2 class="text-lg font-semibold flex items-center gap-2"><x-capstone::icon name="GraduationCap" class="w-5 h-5" /><span x-text="completed?'Hasil Sidang TA':'Sidang TA'"></span></h2><p class="text-sm text-muted-foreground" x-text="completed?'Nilai dan evaluasi sidang tugas akhir Anda':'Your thesis defense schedule and information'"></p></div><div class="px-6 space-y-4">
