        <details x-show="schedule" class="border rounded-lg"><summary class="px-4 py-3 text-sm font-medium text-gray-700 cursor-pointer hover:bg-gray-50">Lihat Jadwal Sidang</summary><div class="px-4 pb-4 pt-2 space-y-2 text-sm">@include('capstone::pages.mahasiswa.ta-submission.schedule-info')</div></details>
