    <div x-show="!completed && schedule" class="bg-blue-50 border border-blue-200 rounded-lg p-4 space-y-3 text-blue-800">@include('capstone::pages.mahasiswa.ta-submission.schedule-info')<div class="h-px bg-blue-200"></div><div class="space-y-2"><p class="text-sm font-medium text-blue-900">Penguji:</p><p class="text-sm" x-text="'1. '+(schedule?.examiner1?.name || 'TBA')"></p><p class="text-sm" x-text="'2. '+(schedule?.examiner2?.name || 'TBA')"></p></div><div x-show="schedule?.evaluation_deadline" class="border-t border-blue-200 pt-3 text-xs text-blue-700" x-text="'Tenggat evaluasi: '+date(schedule?.evaluation_deadline)"></div></div>
    <div x-show="!completed && !schedule" class="bg-yellow-50 border border-yellow-200 rounded-lg p-4 flex gap-3"><x-capstone::icon name="Info" class="h-4 w-4 text-yellow-600 shrink-0" /><div><h3 class="font-medium text-yellow-800">Informasi Jadwal</h3><p class="text-sm text-yellow-700">Sidang TA Anda telah dijadwalkan. Silakan cek halaman jadwal untuk detail lengkap.</p></div></div>
